  'guide.create.why': 'बाकी सब कुछ संगठन से जुड़ा है, इसलिए यहीं से शुरू करें। आप इसके मालिक बन जाते हैं।',
  'guide.venues.why': 'सत्र, कोर्ट और शुल्क वेन्यू से जुड़े होते हैं, इसलिए प्रोग्राम बनाने से पहले अपने प्रशिक्षण स्थान जोड़ें।',
  'guide.staff.why': 'कोच, फ्रंट डेस्क और फ़ाइनेंस को अलग-अलग पहुँच दें। हर व्यक्ति केवल वही देखता है जो उसकी भूमिका को चाहिए।',
  'guide.suppliers.why': 'रखरखाव ठेकेदारों और किट आपूर्तिकर्ताओं को एक जगह रखें, उनके वेन्यू से जोड़ें और अनुरोधों को पूरा होने तक ट्रैक करें।',
  'guide.programmes.why': 'प्रोग्राम वह है जो परिवार खरीदते हैं: एक स्क्वाड, टर्म कोर्स या कैंप, कीमत और सीटों के साथ।',
  'guide.coaches.why': 'कोचों को स्टाफ, ठेकेदार या राजस्व-साझेदार के रूप में जोड़ें और शर्तें लिखित में तय करें।',
  'guide.students.why': 'लोगों को पूछताछ से नामांकन तक ले जाएँ। बच्चों के लिए माता-पिता या अभिभावक सहमति देते हैं।',
  'guide.classes.why': 'आज और सप्ताह एक नज़र में देखें, उपस्थिति लें और मेक-अप व रद्द कक्षाएँ दिखाई देती रखें।',
  'guide.tax.why': 'वसूला और चुकाया गया कर जानें, अपने कर नियमों और इनवॉइस पर कर विवरण के साथ।',
  'guide.revenue.why': 'तय करें कि कोचों के साथ पैसा कैसे बँटेगा और साझा खर्च प्रोग्रामों में कैसे बाँटे जाएँगे।',
  'guide.reports.why': 'कार्यकारी होम पर परिणाम, रिटेंशन, वित्तीय स्थिति और साझेदार देखें, और जो चाहिए उसे एक्सपोर्ट करें।',
